    'course.open': 'Åbn grundkurset',
    'course.open.hint': 'Interaktiv gennemgang af alle tilstande med eksempeldata',
    'course.offer': 'Nyhed: Grundkurset viser hele appen trin for trin med eksempeldata.',
    'course.process.column': 'tusinder',
    'course.viz.chart': 'Folketal pr. län 2024',
    'course.welcome.title': 'Velkommen til Dataspatium',
    'course.welcome.p1': 'Dataspatium henter, bearbejder, analyserer, visualiserer og eksporterer data helt i browseren. Intet skal installeres, og dine data forlader ikke computeren, medmindre du selv henter fra et API.',
    'course.welcome.p2': 'Grundkurset tager omkring ti minutter. Du følger et konkret eksempel, {example}, gennem appens otte tilstande: {modes}. I hvert trin kan du løse opgaven selv eller lade kurset gøre det for dig.',
    'course.welcome.p3': 'Skærmen ser ens ud i alle tilstande: tilstandene øverst, objektpanelet til venstre, arbejdsfladen i midten, egenskaberne til højre og loggen nederst. Kurset kan minimeres og åbnes igen fra hjælpen.',
    'course.import.title': 'Hent: hent data',
    'course.import.p1': 'Alle data i appen ligger i datasæt: tabeller med navngivne kolonner, hvor hver kolonne har en type som tekst, heltal, tal eller dato. Data kan hentes fra filer (CSV, Excel, JSON, Parquet, SPSS med flere), indsat tekst, webadresser og åbne API\'er fra myndigheder i hele Norden.',
    'course.import.task': 'Gå til {mode}, og klik på {button}. Så oprettes datasættet {name}.',
    'course.import.done': 'Datasættet er oprettet: 290 svenske kommuner med kolonnerne kommunkod (kommunekode), kommun (kommune), lanskod (länskode), lan (län), ar (år) og folkmangd (folketal). Kortnavnet er {short}.',
    'course.manage.title': 'Håndter: datasæt og arbejdsområdet',
    'course.manage.p1': 'Hvert datasæt har et navn og et kortnavn. Kortnavnet, her {short}, har kun små bogstaver, cifre og understregninger og bruges i SQL og R. I {mode} ser du kilden, størrelsen, kolonnerne med typer og beskrivelser og versioner, som du kan vende tilbage til.',
    'course.manage.p2': 'Alt gemmes automatisk i browseren. Tag en backup af arbejdsområdet en gang imellem med {backup}, så intet går tabt, hvis browserens data bliver slettet.',
    'course.manage.task': 'Åbn {mode}, vælg datasættet i objektpanelet, og se på oplysningerne og kolonnerne.',
    'course.manage.done': 'Her kan du også ændre navn og kortnavn, dele datasæt som pakker og slette dem.',
    'course.process.title': 'Bearbejd: rens og beregn',
    'course.process.p1': 'I {mode} ser du hele tabellen. Klik på en kolonneoverskrift for at sortere og se kolonnens profil med manglende værdier, unikke værdier og fordeling. Ret værdier direkte i cellerne eller med handlinger.',
    'course.process.p2': 'Hver ændring bliver et trin i datasættets {recipe}. Trinnene kan fortrydes, køres igen på en ny version af data og kopieres som R- eller SQL-kode.',
    'course.process.task': 'Lav en kolonne med folketallet i tusinder: {mode} → {actions} → {group} → {op}. Angiv navnet {column} og udtrykket {expression}.',
    'course.process.done': 'Kolonnen {column} ligger nu sidst i tabellen, og trinnet står i receptet.',
    'course.sql.title': 'Analysér: spørg med SQL',
    'course.sql.p1': '{mode} er tilstanden til kode og statistik. I SQL-fanen hedder det valgte datasæt {data}, men alle datasæt kan også nås med deres kortnavne. Derfor kan én forespørgsel forbinde flere datasæt.',
    'course.sql.task': 'Åbn {mode} → {tab}, skriv forespørgslen nedenfor, og klik på {run}. Forespørgslen summerer folketallet pr. län.',
    'course.sql.done': 'Stockholms län er størst med næsten 2,5 millioner indbyggere, fulgt af Västra Götalands og Skåne län. Med {save} bliver resultatet et nyt datasæt.',
    'course.r.title': 'Analysér: regn med R',
    'course.r.p1': 'R-fanen kører R direkte i browseren med pakker som dplyr og ggplot2. {read} læser et datasæt som en data frame, og {write} gemmer en data frame som et nyt datasæt. Første gang tager det nogle sekunder at starte R.',
    'course.r.task': 'Åbn {mode} → {tab}, skriv koden nedenfor, og klik på {run}. Koden opsummerer folketallet og tegner et histogram.',
    'course.r.done': 'Medianen er godt 16.000 indbyggere: halvdelen af kommunerne er mindre end det, og den største, Stockholm, har næsten en million. Derfor har diagrammet en logaritmisk skala.',
    'course.viz.title': 'Visualisér: lav et diagram',
    'course.viz.p1': 'Diagrammer laves med diagrambyggeren (Vega-Lite), færdige D3-skabeloner eller R. De bruger alle appens farver og skrifttyper, tegnes igen, når data ændres, og kan samles i dashboards med fælles filtre.',
    'course.viz.task': 'Åbn {mode} → {new} → {builder}. Vælg {type}, sæt {x} til lan ({y} er allerede folkmangd), og klik på {save}.',
    'course.viz.done': 'Diagrammet er gemt. Prøv også diagramtypen {map} sammen med eksempeldatasættet {boundaries} for at vise folketallet på et kort.',
    'course.export.title': 'Eksportér: del resultatet',
    'course.export.p1': 'I {mode} gemmer du data som CSV, Excel, JSON, Parquet, SQLite, SPSS og flere formater, diagrammer som PNG, SVG, PDF eller PowerPoint og dokumenter fra skabeloner som Word, PDF, HTML eller LaTeX, også ét dokument pr. gruppe i én kørsel.',
    'course.export.task': 'Åbn {mode}, vælg for eksempel formatet Excel, og klik på {run}.',
    'course.export.done': 'Filen havner blandt browserens overførte filer. Fanerne {charts} og {documents} fungerer på samme måde for diagrammer og dokumenter.',
    'course.finish.title': 'Færdig: sådan går du videre',
    'course.finish.p1': 'Du har været hele kæden igennem: hente, håndtere, bearbejde, analysere, visualisere og eksportere.',
    'course.finish.p2': 'Fortsæt med dine egne data: slip en fil i {import}, vælg lande og hent fra et åbent API, skriv notesbøger med tekst, R og SQL i {analyse}, eller lav dokumentskabeloner i {export}. Alt+1–6 skifter tilstand, og {palette} åbner kommandopaletten.',
    'course.finish.p3': 'Kurset er fortsat tilgængeligt under {help} og i kommandopaletten.',
    'floating.collapse': 'Minimér',
    'floating.expand': 'Vis',
